import{_ as a,o,c as r,a2 as t}from"./chunks/framework.CTeY_0bQ.js";const u=JSON.parse('{"title":"0001 新建 laoshi 库：核心与平台适配器分开","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0001-new-repo-core-and-adapters.md","filePath":"reference/adr/0001-new-repo-core-and-adapters.md","lastUpdated":null}'),i={name:"reference/adr/0001-new-repo-core-and-adapters.md"};function d(s,e,n,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<div><h1 id="_0001-新建-laoshi-库-核心与平台适配器分开" tabindex="-1">0001 新建 laoshi 库：核心与平台适配器分开 <a class="header-anchor" href="#_0001-新建-laoshi-库-核心与平台适配器分开" aria-label="Permalink to &quot;0001 新建 laoshi 库：核心与平台适配器分开&quot;">​</a></h1><ul><li>状态：已采纳</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>req-kit（<code>paseo-req-kit</code>，当前 1.13.0）运行在 Paseo 上。它的引擎已经只通过 <code>AgentRuntime</code> 接口与平台交互（<code>engine/src/runtime.ts</code>，21 个方法，唯一的真实实现是 <code>paseo-runtime.ts</code>），直接绑定 Paseo 的代码约占 engine/src 的 5.7%。但名称、状态文件字段、用户文案、会话识别方式、&quot;以后再做&quot;的实现方式仍然写死了 Paseo，团队也需要在内部自建的 agent 平台上使用同一套流程。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li>新建 <code>laoshi</code> 库，不在 req-kit 库里并行两个版本。原因：两个名字、两条版本线会让 tag、release、CI、站点部署和 issue 互相干扰；laoshi 需要改状态格式和目录结构，不能影响正在使用 1.x 的同事。</li><li>结构分三层：<strong>核心</strong>（平台无关）、<strong>能力契约</strong>（<code>contracts/agent-runtime.md</code>）、<strong>适配器</strong>（每个平台一个）。</li><li>适配器可以由内置初始化 skill 探测平台后生成，但只在安装时生成一次，经人确认后锁定版本，并由 <code>doctor</code> 自检；运行时不现场生成。</li><li>req-kit 进入维护模式：只修缺陷。laoshi 达到对等后，<code>paseo-req-kit</code> 发布 2.0 作为薄分发包。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>过渡期要维护两份，严重缺陷需要按清单移植。</li><li>一致性验收复用 req-kit 的 <code>fake-runtime</code> 编排测试和 <code>evals/</code> 端到端评估。</li><li>命令保留 <code>req</code> 别名，以便老用户迁移。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/docs/adr/0001-new-repo-core-and-adapters.md">docs/adr/0001-new-repo-core-and-adapters.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/docs/adr/0001-new-repo-core-and-adapters.md">在 GitHub 上编辑</a></p>',2)])])}const m=a(i,[["render",d]]);export{u as __pageData,m as default};
